head.script:
scwin.onpageload = function () {
    let arr = [
        { "name" : "홍길동", "col" : "" },
        { "name" : "김철수", "col" : "" }
    ];
    dlt_a.setJSON(arr);
    dlt_b.setJSON(arr);
};

// 편집 종료 300ms 후 col Cell 표시값 / getCellData / DataList 값 / rowStatus 출력
scwin.reportEditEnd = function (name, grd, dlt, rowIndex, colIndex) {
    if (grd.getColumnID(colIndex) !== "col") {
        return;
    }
    setTimeout(function () {
        let td = document.getElementById(grd.id + "_cell_" + rowIndex + "_" + colIndex);
        scwin.setReturnValue("[" + name + "] " + dlt.getCellData(rowIndex, "name") + " 행 col Cell 표시값 : '" + (td ? td.textContent.trim() : "") + "' / getCellData : '" + grd.getCellData(rowIndex, "col")
            + "' / DataList 값 : '" + dlt.getCellData(rowIndex, "col") + "' / rowStatus : " + dlt.getRowStatus(rowIndex));
    }, 300);
};

scwin.grd_a_oneditend = function (rowIndex, colIndex, value) {
    scwin.reportEditEnd("A", grd_a, dlt_a, rowIndex, colIndex);
};

scwin.grd_b_oneditend = function (rowIndex, colIndex, value) {
    scwin.reportEditEnd("B", grd_b, dlt_b, rowIndex, colIndex);
};

// 리턴 값 초기화
scwin.btn_clear_onclick = function (e) {
    tbx_return.setValue("");
};

// 리턴 값 설정
scwin.setReturnValue = function (strValue) {
    tbx_return.setValue(tbx_return.getValue() + strValue);
    tbx_return.setValue(tbx_return.getValue() + "\n");
};
